import { canonicalizeBundle, canonicalizeBundleFiles, stableJson, verificationClaimsSchema, type CanonicalBundle, type R2BundleRepository, type SkillDependency } from "@skillplane/storage";
import type { Pool, PoolClient } from "pg";
import { authorize } from "./authorization.js";
import { DomainError } from "./errors.js";
import type { Principal } from "./principal.js";
import { compositionDigest, emptyLock, resolveDependencies, validateLock, type CompositionPlan, type DependencyChoice, type DependencyLock, type DependencyNode, type ResolvedModule } from "./composition.js";

type Queryable = Pick<Pool, "query"> | Pick<PoolClient,"query">;
interface Source {
  id: string; workspace_id: string; skill_id: string; workspace_slug: string; skill_slug: string;
  semantic_version: string; content_digest: `sha256:${string}`; r2_object_key: string;
  visibility: string; status: string; deprecated_at: Date | null; revoked_at: Date | null;
  bundle: CanonicalBundle; publicSource: boolean;
}
export interface PreparedComposition { bundle: CanonicalBundle; lock: DependencyLock; closureDigest: string }

export class CompositionService {
  constructor(readonly pool: Pool, readonly storage: R2BundleRepository, readonly controlPool: Pool = pool, readonly publicStorage: R2BundleRepository = storage) {}

  private denied(): never { throw new DomainError("SKILL_DEPENDENCY_CONFLICT","Dependency is unavailable or inaccessible",409); }
  private async workspaceSlug(workspaceId: string): Promise<string> {
    const result = await this.controlPool.query<{slug: string}>("SELECT slug FROM workspaces WHERE id = $1",[workspaceId]);
    if (!result.rows[0]) this.denied();
    return result.rows[0].slug;
  }
  private async source(versionId: string, principal: Principal | null, db: Queryable = this.pool): Promise<Source> {
    const result = await db.query<Omit<Source,"bundle" | "workspace_slug" | "publicSource">>(
      `SELECT v.id, v.workspace_id, v.skill_id, s.slug AS skill_slug,
              v.semantic_version, v.content_digest, v.r2_object_key, s.visibility, v.status,
              lifecycle.deprecated_at, lifecycle.revoked_at
         FROM skill_versions v JOIN skills s ON s.id = v.skill_id
         LEFT JOIN skill_version_lifecycle lifecycle ON lifecycle.version_id = v.id
        WHERE v.id = $1 AND (s.workspace_id = $2 OR s.visibility = 'public')`, [versionId,principal?.workspaceId ?? null]);
    const row = result.rows[0];
    if (row) {
      if (row.revoked_at) throw new DomainError("SKILL_VERSION_REVOKED","A required version was revoked",409);
      if (row.workspace_id !== principal?.workspaceId && row.visibility !== "public") this.denied();
      const stored = await this.storage.getCanonicalBundle(row.r2_object_key,row.content_digest);
      return {...row, workspace_slug:await this.workspaceSlug(row.workspace_id),bundle:await canonicalizeBundle(stored.bytes),publicSource:false};
    }
    const projection = await this.controlPool.query<{
      version_id: string; workspace_id: string; workspace_slug: string; skill_id: string; skill_slug: string;
      semantic_version: string; digest: `sha256:${string}`; object_key: string;
    }>(`SELECT p.* FROM public_skill_projections p JOIN public_skill_projection_heads h
        ON h.workspace_id = p.workspace_id AND h.skill_id = p.skill_id AND h.state = 'published'
        WHERE p.version_id = $1`,[versionId]);
    const remote = projection.rows[0];
    if (!remote) this.denied();
    const stored = await this.publicStorage.getCanonicalBundle(remote.object_key,remote.digest);
    return {id:remote.version_id,workspace_id:remote.workspace_id,workspace_slug:remote.workspace_slug,skill_id:remote.skill_id,skill_slug:remote.skill_slug,semantic_version:remote.semantic_version,content_digest:remote.digest,r2_object_key:remote.object_key,visibility:"public",status:"published",deprecated_at:null,revoked_at:null,bundle:await canonicalizeBundle(stored.bytes),publicSource:true};
  }
  private lock(bundle: CanonicalBundle): DependencyLock {
    if (bundle.skill.formatVersion === 1) return emptyLock();
    const bytes = bundle.files.get("skill.lock.json");
    if (!bytes) throw new DomainError("SKILL_DEPENDENCY_CONFLICT","Composite is missing its server lock",409);
    try {
      const lock = JSON.parse(new TextDecoder().decode(bytes)) as DependencyLock;
      if (!Array.isArray(lock.nodes) || !Array.isArray(lock.edges)) this.denied();
      return lock;
    } catch { return this.denied(); }
  }
  private async node(source: Source): Promise<DependencyNode> {
    const lock = this.lock(source.bundle);
    validateLock(lock,{workspace:source.workspace_slug,skill:source.skill_slug,expandedBytes:source.bundle.manifest.expandedByteSize});
    if (source.bundle.digest !== source.content_digest) this.denied();
    return {versionId:source.id,workspaceId:source.workspace_id,skillId:source.skill_id,workspace:source.workspace_slug,skill:source.skill_slug,semanticVersion:source.semantic_version,digest:source.content_digest,closureDigest:await compositionDigest(source.content_digest,lock),expandedBytes:source.bundle.manifest.expandedByteSize};
  }
  private async choices(dependency: SkillDependency, principal: Principal): Promise<DependencyChoice[]> {
    const workspace = await this.controlPool.query<{id: string}>("SELECT id FROM workspaces WHERE slug = $1",[dependency.workspace]);
    const workspaceId = workspace.rows[0]?.id;
    if (!workspaceId) this.denied();
    const rows = await this.pool.query<{id: string}>(`SELECT v.id FROM skill_versions v JOIN skills s ON s.id = v.skill_id
      LEFT JOIN skill_version_lifecycle lifecycle ON lifecycle.version_id = v.id
      WHERE s.workspace_id = $1 AND s.slug = $2 AND v.status = 'published'
      AND (s.workspace_id = $3 OR s.visibility = 'public') AND lifecycle.revoked_at IS NULL
      ORDER BY v.revision DESC LIMIT 101`,[workspaceId,dependency.skill,principal.workspaceId]);
    let ids = rows.rows.map(r=>r.id);
    if (!ids.length && workspaceId !== principal.workspaceId) {
      const publicRows = await this.controlPool.query<{version_id:string}>(`SELECT p.version_id FROM public_skill_projections p JOIN public_skill_projection_heads h
        ON h.workspace_id = p.workspace_id AND h.skill_id = p.skill_id AND h.state = 'published'
        WHERE p.workspace_slug = $1 AND p.skill_slug = $2 ORDER BY p.published_at DESC LIMIT 101`,[dependency.workspace,dependency.skill]);
      ids = publicRows.rows.map(r=>r.version_id);
    }
    if (ids.length > 100) throw new DomainError("SKILL_DEPENDENCY_CONFLICT","Too many dependency versions; use a narrower publication catalog",409);
    const choices: DependencyChoice[] = [];
    for (const id of ids) {
      const source = await this.source(id,principal);
      choices.push({node:await this.node(source),lock:this.lock(source.bundle)});
    }
    return choices;
  }
  async prepare(bundle: CanonicalBundle, principal: Principal, visibility: string, preserveLock = false): Promise<PreparedComposition> {
    if (bundle.skill.formatVersion === 1) return {bundle,lock:emptyLock(),closureDigest:await compositionDigest(bundle.digest,emptyLock())};
    authorize(principal,"skills:read");
    const files = new Map(bundle.files); files.delete("skill.lock.json");
    const authored = await canonicalizeBundleFiles({skill:bundle.skill,files});
    const root = {workspace:await this.workspaceSlug(principal.workspaceId),skill:bundle.skill.slug,expandedBytes:authored.manifest.expandedByteSize};
    const lock = preserveLock ? this.lock(bundle) : await resolveDependencies({dependencies:bundle.skill.dependencies,root,choices:d=>this.choices(d,principal)});
    validateLock(lock,root);
    await this.revalidate(lock,principal,visibility);
    files.set("skill.lock.json",new TextEncoder().encode(`${stableJson(lock)}\n`));
    const canonical = await canonicalizeBundleFiles({skill:bundle.skill,files});
    validateLock(lock,{...root,expandedBytes:canonical.manifest.expandedByteSize});
    return {bundle:canonical,lock,closureDigest:await compositionDigest(canonical.digest,lock)};
  }
  async revalidate(lock: DependencyLock, principal: Principal | null, visibility: string, db: Queryable = this.pool): Promise<void> {
    for (const locked of lock.nodes) {
      const source = await this.source(locked.versionId,principal,db);
      if (source.status !== "published") this.denied();
      if ((visibility === "public" || source.workspace_id !== principal?.workspaceId) && source.visibility !== "public") this.denied();
      if (visibility === "workspace" && source.visibility === "private") this.denied();
      if (stableJson(await this.node(source)) !== stableJson(locked)) throw new DomainError("SKILL_DEPENDENCY_CONFLICT","Locked dependency identity changed",409);
    }
  }
  async persist(client: PoolClient, versionId: string, workspaceId: string, prepared: PreparedComposition): Promise<void> {
