import type { Pool, PoolClient } from "pg";
import { authorize } from "./authorization.js";
import { CompositionService } from "./composition-service.js";
import type { CompositionPlan, ResolvedClaim } from "./composition.js";
import { DomainError } from "./errors.js";
import { hashIdempotentRequest, type IdempotencyStore } from "./idempotency.js";
import { insertPrincipalAudit } from "./mutation-audit.js";
import { principalAuditActor, type Principal } from "./principal.js";
import { withDomainTransaction } from "./transactions.js";

export interface EvidenceReference { type: string; uri: string; sha256: string; description: string; redacted: true }
export interface ClaimResult { claimId: string; status: "pass" | "fail" | "unknown"; explanation: string; evidence: EvidenceReference[] }
interface Mutation { principal: Principal; idempotencyKey: string; requestId: string; fencingEpoch?: number }
export interface VerificationRun {
  id: string; workspace_id: string; version_id: string; closure_digest: string; repository: string;
  commit_sha: string; environment: string; verifier_actor_id: string; verifier_actor_type: string;
  executor_actor_id: string; agent: string; model: string; status: "running" | "pass" | "fail" | "unknown";
  plan: CompositionPlan["verificationPlan"]; evidence_manifest_digest: string | null; expires_at: Date;
}
function invalid(message: string): never { throw new DomainError("VERIFICATION_INVALID",message,400); }
function bounded(value: string, name: string, max = 2000): string {
  if (typeof value !== "string" || !value.trim() || value.length > max || /\0/.test(value)) invalid(`Invalid ${name}`);
  return value.trim();
}
export function evaluateVerification(claims: readonly ResolvedClaim[], results: readonly ClaimResult[]): "pass" | "fail" | "unknown" {
  let unknown = false;
  for (const claim of claims.filter(c=>c.severity==="blocking")) {
    const result = results.find(r=>r.claimId===claim.namespacedId);
    if (result?.status==="fail") return "fail";
    if (!result || result.status==="unknown" || claim.requiredEvidence.some(type=>!result.evidence.some(e=>e.type===type))) unknown=true;
  }
  return unknown ? "unknown" : "pass";
}
export class VerificationService {
  constructor(readonly pool: Pool, readonly composition: CompositionService, readonly idempotency: IdempotencyStore) {}
  private async mutate<T>(options: Mutation, operation: string, payload: unknown, work: (client: PoolClient)=>Promise<T>): Promise<T> {
    authorize(options.principal,"skills:read");
    const claim = await this.idempotency.claim<{result:T}>({workspaceId:options.principal.workspaceId,principal:options.principal,operation,key:options.idempotencyKey,requestHash:await hashIdempotentRequest(payload),fencingEpoch:options.fencingEpoch});
