      const claim=run.plan.claims.find(c=>c.namespacedId===result.claimId);
      if(!claim) invalid("Claim is outside the locked verification plan");
      if(result.status==="pass" && claim.requiredEvidence.some(type=>!result.evidence.some(e=>e.type===type))) invalid("Passing claims require every declared evidence type");
      await client.query(`INSERT INTO skill_verification_claim_results (workspace_id,run_id,namespaced_claim_id,originating_version_id,status,explanation,evidence)
        VALUES ($1,$2,$3,$4,$5,$6,$7) ON CONFLICT (run_id,namespaced_claim_id) DO UPDATE SET status=EXCLUDED.status,explanation=EXCLUDED.explanation,evidence=EXCLUDED.evidence`,[options.principal.workspaceId,run.id,result.claimId,claim.originatingVersionId,result.status,result.explanation,JSON.stringify(result.evidence)]);
      return {id:run.id,result};
    });
  }
  async complete(options:Mutation & {runId:string}) {
    return this.mutate(options,"skill.verification.completed",{runId:options.runId},async client=>{
      const run=await this.run(client,options.runId,options.principal,true);
      const rows=await client.query<{namespaced_claim_id:string;status:ClaimResult["status"];explanation:string;evidence:EvidenceReference[]}>("SELECT * FROM skill_verification_claim_results WHERE run_id=$1 AND workspace_id=$2 ORDER BY namespaced_claim_id",[run.id,options.principal.workspaceId]);
