        await this.idempotency.complete(client,claim.identity,200,{result:payload});return payload;
      },{fencingEpoch:options.fencingEpoch});
    }catch(error){await this.idempotency.release(claim.identity,options.fencingEpoch).catch(()=>undefined);throw error;}
