   const {canonicalizeBundle,canonicalizeBundleFiles}=await import("@skillplane/storage");
   const base=await canonicalizeBundle(stored.bytes);const files=new Map(base.files);files.delete("skill.lock.json");
   if(input.verifierInstructions && input.claimsJson){files.set("verification/VERIFY.md",new TextEncoder().encode(input.verifierInstructions));files.set("verification/claims.json",new TextEncoder().encode(input.claimsJson));}
