import { Pool } from "pg";
if(!process.env.DATABASE_URL)throw new Error("DATABASE_URL must identify the regional database");
const pool=new Pool({connectionString:process.env.DATABASE_URL,max:1});
try {
 const client=await pool.connect();
 try {
  await client.query("BEGIN");
  const expired=await client.query("SELECT id FROM skill_verification_runs WHERE expires_at <= now() ORDER BY expires_at LIMIT 500 FOR UPDATE SKIP LOCKED");
  const ids=expired.rows.map(row=>row.id);
  await client.query("DELETE FROM skill_verification_claim_results WHERE run_id=ANY($1::text[])",[ids]);
  const result=await client.query("DELETE FROM skill_verification_runs WHERE id=ANY($1::text[])",[ids]);
  await client.query("COMMIT");console.log(JSON.stringify({event:"verification.retention",deletedRuns:result.rowCount}));
 } catch(error){await client.query("ROLLBACK");throw error;}finally{client.release();}
}finally{await pool.end();}
